import Mathlib

open Multiset

def BaseSkewT4 : Fin 4 → Multiset (ℕ × ℕ)
  | 1 => {(0, 0), (1, 0), (1, 1), (2, 1)}
  | 2 => {(1, 0), (1, 1), (0, 1), (0, 2)}
  | 3 => {(0, 1), (1, 1), (1, 0), (2, 0)}
  | 4 => {(0, 0), (0, 1), (1, 1), (1, 2)}

def SkewT4 (q : Fin 4 × ℕ × ℕ) : Multiset (ℕ × ℕ) :=
  (BaseSkewT4 q.1).map λ p ↦ q.2 + p

theorem imo_sl_2014_C4 {P Q : Multiset (Fin 4 × ℕ × ℕ)}
    (h : (map SkewT4 P).sum = (map SkewT4 Q).sum) (i : Fin 4) :
    (P.map Prod.fst).count i % 2 = (Q.map Prod.fst).count i % 2 := by
  fin_cases i <;> simp only [Fin.isValue] <;>
  · have key := congr_arg (fun s : Multiset (ℕ × ℕ) =>
        (s.map (fun p : ℕ × ℕ => p.1 % 2)).count 0 % 2) h
    simp only [BaseSkewT4, SkewT4, Multiset.map_map, Function.comp,
               Multiset.sum_map_add, Multiset.map_add, Multiset.count_add,
               Multiset.map_sum, Multiset.count_sum] at key
    simp only [Multiset.map_map, Function.comp, Prod.fst, Prod.snd,
               Nat.add_mod, Nat.mod_mod_of_dvd] at key
    omega
